import fotoHeader from '../img/foto-header.jpg';
import { useNavigate } from "react-router-dom";

export default function Header() {

  const navigate = useNavigate();
  
  const transitionPlanClient = () => {
    navigate(`/portfolio`);
  };

return (
<div className='header'>
<div className="header__row">
  <div className="_container">
<div className="header__nav">
    <div className="header__nav-nav">
      <ul>
        <li><p>home</p></li>
        <li onClick={transitionPlanClient}><p>portfolio</p></li>
        <li><p>contacts</p></li>
      </ul>
    </div>
  </div>
  <div className="header__title"><h1>Vitalii Antonenko</h1></div>
  <div className="header__img">
    <img src={fotoHeader} alt="" />
  </div>
  <div className="header__text"><p>moments of your life</p></div>


  </div>
  
</div>
 </div>
);
}
